try {
    $pdo = db(); $databaseAvailable = true; $user = current_user();
} catch (Throwable $e) {
    error_log((string)$e); $databaseAvailable = false; $user = null; $pdo = null;
}

if ($page === 'availability') {
    header('Content-Type: application/json; charset=utf-8');
    header('Cache-Control: no-store');
    if (!$databaseAvailable) { http_response_code(503); echo json_encode(['slots'=>[],'error'=>'Booking setup is being completed.']); exit; }
    try {
        $slots = (new BookingService($pdo))->slots((int)($_GET['service_id'] ?? 0),(int)($_GET['stylist_id'] ?? 0),(string)($_GET['date'] ?? ''));
        echo json_encode(['slots'=>$slots], JSON_THROW_ON_ERROR);
    } catch (Throwable $e) { http_response_code(400); echo json_encode(['slots'=>[]]); }
    exit;
}

$flashMessage = take_flash();
$services = $databaseAvailable ? (new BookingService($pdo))->services() : [
    ['id'=>1,'name'=>'Signature cut','description'=>'A considered cut, wash and finish, shaped around your hair and your day.','duration_minutes'=>60,'price_cents'=>6800],
    ['id'=>2,'name'=>'Gloss & blow dry','description'=>'A soft, luminous finish with a custom gloss and a polished blow dry.','duration_minutes'=>75,'price_cents'=>9200],
