    ['id'=>5,'name'=>'Bridal styling','description'=>'An unhurried styling appointment for celebrations and special occasions.','duration_minutes'=>90,'price_cents'=>14500],
];
$stylists = $databaseAvailable ? (new BookingService($pdo))->stylists() : [
    ['id'=>1,'name'=>'Amara James','title'=>'Creative Director','bio'=>'Thoughtful shapes, effortless movement and hair that feels like you.','accent'=>'#c48470'],
    ['id'=>2,'name'=>'Maya Laurent','title'=>'Colour Specialist','bio'=>'Soft dimension and lived-in colour, tailored to your natural tone.','accent'=>'#8f9c80'],
    ['id'=>3,'name'=>'Nina Park','title'=>'Senior Stylist','bio'=>'Modern cuts and a calm, considered approach to every appointment.','accent'=>'#b291a1'],
    ['id'=>4,'name'=>'Sofia Reyes','title'=>'Stylist','bio'=>'Beautiful, practical styling with a little extra attention to detail.','accent'=>'#d2a462'],
];
