 ['url'=>'https://images.unsplash.com/photo-1664293344021-6e960f2df71b?auto=format&fit=crop&w=900&q=85','alt'=>'Curly-haired client, sample portrait'],
 ['url'=>'https://images.unsplash.com/photo-1551438632-cacd75df629f?auto=format&fit=crop&w=900&q=85','alt'=>'Client with natural curls, sample portrait'],
