 ['url'=>'https://images.unsplash.com/photo-1553148619-669d4311dd55?auto=format&fit=crop&w=900&q=85','alt'=>'Client with curly hair, sample portrait'],
];
$fmtPrice = static fn($cents) => money((int)$cents);
$dayValue = (string)($_GET['date'] ?? date('Y-m-d'));
$upcoming = $past = [];
if ($databaseAvailable && $user && $page === 'account') {
    $q = $pdo->prepare("SELECT a.*,sv.name service,sv.duration_minutes,sv.price_cents,st.name stylist FROM appointments a JOIN services sv ON sv.id=a.service_id JOIN stylists st ON st.id=a.stylist_id WHERE a.customer_id=? ORDER BY a.starts_at DESC");
    $q->execute([$user['id']]);
    foreach ($q->fetchAll() as $appointment) {
        if ($appointment['status']==='confirmed' && $appointment['starts_at'] > date('Y-m-d H:i:s')) $upcoming[]=$appointment;
        else $past[]=$appointment;
    }
}
$adminAppointments = [];
$staffLink = null;
if ($databaseAvailable && $user && in_array($user['role'],['owner','stylist'],true) && in_array($page,['admin','customers'],true)) {
    $staffQ=$pdo->prepare('SELECT id FROM stylists WHERE user_id=?'); $staffQ->execute([$user['id']]); $staffLink=(int)($staffQ->fetchColumn() ?: 0);
}
if ($databaseAvailable && $user && in_array($user['role'],['owner','stylist'],true) && $page==='admin') {
    $date = DateTimeImmutable::createFromFormat('!Y-m-d',$dayValue) ?: new DateTimeImmutable('today');
    $weekView = (($_GET['view'] ?? 'day')==='week');
    $from = $weekView ? $date->modify('monday this week')->format('Y-m-d 00:00:00') : $date->format('Y-m-d 00:00:00');
    $to = $weekView ? $date->modify('monday this week')->modify('+7 days')->format('Y-m-d 00:00:00') : $date->modify('+1 day')->format('Y-m-d 00:00:00');
    $sql="SELECT a.*,u.name customer,u.email,sv.name service,sv.duration_minutes,st.name stylist,st.user_id stylist_user FROM appointments a JOIN users u ON u.id=a.customer_id JOIN services sv ON sv.id=a.service_id JOIN stylists st ON st.id=a.stylist_id WHERE a.starts_at>=? AND a.starts_at<?";
    $args=[$from,$to]; if ($user['role']==='stylist') {$sql.=' AND st.user_id=?';$args[]=$user['id'];}
    $sql.=" ORDER BY a.starts_at"; $q=$pdo->prepare($sql);$q->execute($args);$adminAppointments=$q->fetchAll();
}

