ancel</button></form></div></article><?php endforeach; ?></div><?php endif; ?><div class="account-section-title past-title"><h2>Past visits <span><?= count($past) ?></span></h2><div class="account-rule"></div></div><?php if($past): ?><div class="past-list"><?php foreach(array_slice($past,0,12) as $a): ?><div class="past-row"><span><?= h(date('M j, Y',strtotime($a['starts_at']))) ?></span><strong><?= h($a['service']) ?></strong><span><?= h($a['stylist']) ?></span><span class="past-status"><?= h(ucwords(str_replace('_',' ',$a['status']))) ?></span></div><?php endforeach; ?></div><?php else: ?><p class="muted">Your past visits will show up here.</p><?php endif; ?></section><?php endif; ?>

