ngs-form compact-form"><?= csrf_field() ?><input type="hidden" name="action" value="save_service"><input type="hidden" name="id" value="<?= (int)($editService['id']??0) ?>"><label>Service name<input name="name" required maxlength="120" value="<?= h($editService['name']??'') ?>" placeholder="e.g. Fringe trim"></label><div class="form-two"><label>Duration (minutes)<input type="number" name="duration" min="15" max="480" value="<?= (int)($editService['duration_minutes']??60) ?>" required></label><label>Starting price<input type="number" name="price" min="0" step="1" value="<?= isset($editService['price_cents'])?h((string)($editService['price_cents']/100)):'' ?>" placeholder="65" required></label></div><label>Short description<textarea name="description" rows="2" maxlength="1500"><?= h($editService['description']??'') ?></textarea></label><button class="button button-dark"><?= $editService?'Save service':'Add service' ?> <span>↗</span></button></form><div class="settings-items"><?php foreach($allServices as $s): ?><div class="settings-item"><div><strong><?= h($s['name']) ?></strong><small><?= (int)$s['duration_minutes'] ?> min · <?= $fmtPrice($s['price_cents']) ?> · <?= $s['is_active']?'Visible':'Hidden' ?></small></div><a class="mini-link" href="/?page=manage&edit_service=<?= (int)$s['id'] ?>">Edit</a><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="toggle_service"><input type="hidden" name="id" value="<?= (int)$s['id'] ?>"><button class="mini-link"><?= $s['is_active']?'Hide':'Restore' ?></button></form></div><?php endforeach; ?></div></section>
