oliday, training..."></label><button class="button button-dark">Save blocked time <span>↗</span></button></form><div class="settings-card"><p class="eyebrow">UP NEXT</p><h2>Upcoming blocks</h2><?php if(!$blockRows): ?><p class="muted">No blocked time coming up.</p><?php else: foreach($blockRows as $b): ?><div class="settings-item"><div><strong><?= h($b['reason']) ?></strong><small><?= h(date_label($b['starts_at'])) ?> – <?= h(date('g:i a',strtotime($b['ends_at']))) ?><br><?= h($b['stylist']??'Everyone') ?></small></div><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="remove_block"><input type="hidden" name="id" value="<?= (int)$b['id'] ?>"><button class="mini-link">Remove</button></form></div><?php endforeach; endif; ?></div></div></div></section><?php endif; ?>

<?php elseif ($page==='customers'): ?>
<?php if(!$user || !in_array($user['role'],['owner','stylist'],true)): ?><section class="auth-wrap shell"><div class="auth-content"><p class="eyebrow">Studio team</p><h1>Client <em>book.</em></h1><a href="/?page=login" class="button button-dark">Staff sign in</a></div></section><?php else: $search=trim((string)($_GET['q']??''));$customerId=(int)($_GET['id']??0);$args=[];if($user['role']==='stylist'){$sql="SELECT u.id,u.name,u.email,COUNT(DISTINCT a.id) bookings,MAX(a.starts_at) last_visit FROM users u JOIN appointments a ON a.customer_id=u.id JOIN stylists st ON st.id=a.stylist_id WHERE st.user_id=? AND u.role='customer'";$args[]=$user['id'];}else{$sql="SELECT u.id,u.name,u.email,COUNT(a.id) bookings,MAX(a.starts_at) last_visit FROM users u LEFT JOIN appointments a ON a.customer_id=u.id WHERE u.role='customer'";}if($search!==''){$sql.=' AND (u.name LIKE ? OR u.email LIKE ?)';$args[]='%'.$search.'%';$args[]='%'.$search.'%';}$sql.=' GROUP BY u.id ORDER BY u.name LIMIT 100';$q=$pdo->prepare($sql);$q->execute($args);$clients=$q->fetchAll();$selected=null;$history=[];$notes=[];if($customerId){foreach($clients as $c)if((int)$c['id']===$customerId)$selected=$c;if($selected){$q=$pdo->prepare('SELECT a.*,sv.name service,st.name stylist FROM appointments a JOIN services sv ON sv.id=a.service_id JOIN stylists st ON st.id=a.stylist_id WHERE a.customer_id=? '.($user['role']==='stylist'?'AND st.user_id=? ':'').'ORDER BY a.starts_at DESC LIMIT 30');$q->execute($user['role']==='stylist'?[$customerId,$user['id']]:[$customerId]);$history=$q->fetchAll();$q=$pdo->prepare('SELECT n.*,u.name author FROM customer_notes n JOIN users u ON u.id=n.author_id WHERE n.customer_id=? ORDER BY n.created_at DESC');$q->execute([$customerId]);$notes=$q->fetchAll();}} ?><section class="admin-shell shell"><aside class="admin-side"><div class="admin-side-head"><span class="admin-avatar"><?= h(mb_substr($user['name'],0,1)) ?></span><div><strong><?= h($user['name']) ?></strong><small><?= h(ucfirst($user['role'])) ?> access</small></div></div><nav><a href="/?page=admin">◷ <span>Calendar</span></a><a class="admin-nav-active" href="/?page=customers">♙ <span>Clients</span></a><?php if($user['role']==='owner'): ?><a href="/?page=manage">⚙ <span>Studio settings</span></a><a href="/?page=blocks">▦ <span>Blocked time</span></a><a href="/?page=reports">▤ <span>Reports</span></a><?php endif; ?></nav></aside><div class="admin-main"><div class="admin-title-row"><div><p class="eyebrow">LUMA STUDIO / THE PEOPLE WHO MAKE IT LOVELY</p><h1>Client <em>book.</em></h1></div><a class="button button-outline" href="/?page=admin">← Calendar</a></div><form class="search-form" method="get"><input type="hidden" name="page" value="customers"><input type="search" name="q" value="<?= h($search) ?>" placeholder="Search by name or email"><button class="button button-outline">Search</button></form><div class="clients-layout"><div class="client-list"><?php foreach($clients as $c): ?><a class="client-row <?= (int)$customerId===(int)$c['id']?'client-selected':'' ?>" href="/?page=customers&id=<?= (int)$c['id'] ?>&q=<?= rawurlencode($search) ?>"><span class="client-avatar"><?= h(mb_substr($c['name'],0,1)) ?></span><span><strong><?= h($c['name']) ?></strong><small><?= h($c['email']) ?></small></span><span class="client-count"><?= (int)$c['bookings'] ?></span></a><?php endforeach; ?><?php if(!$clients): ?><p class="muted">No clients found.</p><?php endif; ?></div><?php if($selected): ?><div class="client-detail"><div class="client-detail-head"><span class="client-avatar client-avatar-large"><?= h(mb_substr($selected['name'],0,1)) ?></span><div><p class="eyebrow">CLIENT PROFILE</p><h2><?= h($selected['name']) ?></h2><a href="mailto:<?= h($selected['email']) ?>"><?= h($selected['email']) ?></a></div></div><div class="client-history"><h3>Booking history</h3><?php foreach($history as $a): ?><div class="past-row"><span><?= h(date('M j, Y',strtotime($a['starts_at']))) ?></span><strong><?= h($a['service']) ?></strong><span><?= h($a['stylist']) ?></span><span class="past-status"><?= h(ucwords(str_replace('_',' ',$a['status']))) ?></span></div><?php endforeach; ?></div><div class="client-notes"><h3>Studio notes <span>PRIVATE</span></h3><?php foreach($notes as $n): ?><article><p><?= nl2br(h($n['note'])) ?></p><small><?= h($n['author']) ?> · <?= h(date('M j, Y',strtotime($n['created_at']))) ?></small></article><?php endforeach; ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="add_note"><input type="hidden" name="customer_id" value="<?= (int)$selected['id'] ?>"><input type="hidden" name="return_page" value="customers"><input type="hidden" name="return_id" value="<?= (int)$selected['id'] ?>"><textarea name="note" rows="3" maxlength="2000" required placeholder="Add a note for the team..."></textarea><button class="button button-outline">Add note <span>+</span></button></form></div></div><?php else: ?><div class="client-detail client-detail-empty"><span>←</span><p>Choose a client to see their visits and studio notes.</p></div><?php endif; ?></div></div></section><?php endif; ?>

<?php elseif ($page==='reports'): ?>
<?php if(!$user || $user['role']!=='owner'): ?><section class="page-intro shell"><p class="eyebrow">Owner access</p><h1>Studio <em>report.</em></h1><p>Reports are available to the studio owner.</p></section><?php else: $weekStart=(new DateTimeImmutable('monday this week'))->format('Y-m-d 00:00:00');$nextWeek=(new DateTimeImmutable('monday next week'))->format('Y-m-d 00:00:00');$q=$pdo->prepare("SELECT COUNT(*) total,SUM(CASE WHEN status IN ('confirmed','completed') THEN price_cents ELSE 0 END) revenue FROM appointments a JOIN services s ON s.id=a.service_id WHERE starts_at>=? AND starts_at<?");$q->execute([$weekStart,$nextWeek]);$weekStats=$q->fetch();$q=$pdo->prepare("SELECT s.name,COUNT(*) total FROM appointments a JOIN services s ON s.id=a.service_id WHERE starts_at>=? AND starts_at<? AND status IN ('confirmed','completed') GROUP BY s.id ORDER BY total DESC LIMIT 5");$q->execute([$weekStart,$nextWeek]);$popular=$q->fetchAll();$weeklyStart=(new DateTimeImmutable('monday this week'))->modify('-7 weeks')->format('Y-m-d 00:00:00');$q=$pdo->prepare("SELECT DATE_FORMAT(starts_at,'%x-W%v') week,COUNT(*) bookings,SUM(CASE WHEN status IN ('confirmed','completed') THEN price_cents ELSE 0 END) revenue FROM appointments WHERE starts_at>=? AND starts_at<? GROUP BY DATE_FORMAT(starts_at,'%x-W%v') ORDER BY week");$q->execute([$weeklyStart,$nextWeek]);$weekly=$q->fetchAll(); ?><section class="admin-shell shell"><aside class="admin-side"><div class="admin-side-head"><span class="admin-avatar">L</span><div><strong><?= h($user['name']) ?></strong><small>Owner access</small></div></div><nav><a href="/?page=admin">◷ <span>Calendar</span></a><a href="/?page=customers">♙ <span>Clients</span></a><a href="/?page=manage">⚙ <span>Studio settings</span></a><a href="/?page=blocks">▦ <span>Blocked time</span></a><a class="admin-nav-active" href="/?page=reports">▤ <span>Reports</span></a></nav></aside><div class="admin-main"><div class="admin-title-row"><div><p class="eyebrow">OWNER / THE STUDIO, IN NUMBERS</p><h1>Studio <em>report.</em></h1></div><span class="report-period">THIS WEEK · <?= h(date('M j',strtotime($weekStart))) ?>—<?= h(date('M j',strtotime($nextWeek.' -1 day'))) ?></span></div><div class="report-cards"><div class="report-card"><span>BOOKINGS THIS WEEK</span><strong><?= (int)$weekStats['total'] ?></strong><small>appointments in all statuses</small></div><div class="report-card"><span>BOOKED REVENUE</span><strong><?= money((int)($weekStats['revenue']??0)) ?></strong><small>confirmed and completed</small></div><div class="report-card"><span>TOP SERVICE</span><strong class="report-service"><?= h($popular[0]['name']??'—') ?></strong><small><?= (int)($popular[0]['total']??0) ?> bookings this week</small></div></div><div class="report-grid"><section class="settings-card"><p class="eyebrow">THE LAST EIGHT WEEKS</p><h2>Bookings & revenue</h2><div class="report-table"><div class="report-table-head"><span>WEEK</span><span>BOOKINGS</span><span>REVENUE</span></div><?php foreach($weekly as $w): ?><div class="report-row"><span><?= h($w['week']) ?></span><strong><?= (int)$w['bookings'] ?></strong><span><?= money((int)$w['revenue']) ?></span></div><?php endforeach; ?><?php if(!$weekly): ?><p class="muted">Your first week of bookings will show here.</p><?php endif; ?></div></section><section class="settings-card"><p class="eyebrow">THIS WEEK</p><h2>Popular services</h2><?php foreach($popular as $i=>$p): ?><div class="popular-service"><span class="popular-rank">0<?= $i+1 ?></span><div><strong><?= h($p['name']) ?></strong><div class="bar-track"><span style="width:<?= max(8,(int)round(100*(int)$p['total']/max(1,(int)($popular[0]['total']??1)))) ?>%"></span></div></div><b><?= (int)$p['total'] ?></b></div><?php endforeach; ?><?php if(!$popular): ?><p class="muted">No appointments this week yet.</p><?php endif; ?></section></div></div></section><?php endif; ?>

<?php else: ?><section class="page-intro shell"><p class="eyebrow">Luma Studio</p><h1>Page not <em>found.</em></h1><a href="/" class="button button-dark">Back home <span>→</span></a></section><?php endif; ?>
